1	// Package fakenexus replays recorded Nexus answers over loopback HTTP. It is the
2	// only package of the fixture tree that imports testing: the recorder and the
3	// nexus-bench binary stay free of it (nexusfixture itself must not import it).
4	// Import it from _test.go files only.
5	package fakenexus
6	
7	import (
8		"encoding/json"
9		"net/http"
10		"net/http/httptest"
11		"net/url"
12		"regexp"
13		"strconv"
14		"strings"
15		"sync"
16		"testing"
17	
18		"github.com/anthnel/devdesk/internal/nexusfixture"
19	)
20	
21	// Password is the password the fake accepts for every account.
22	const Password = "REDACTED"
23	
24	// User returns the user name an identity authenticates as; anonymous has none.
25	func User(id nexusfixture.Identity) string {
26		switch id {
27		case nexusfixture.Admin:
28			return "admin"
29		case nexusfixture.Pull:
30			return "bench-pull"
31		default:
32			return ""
33		}
34	}
35	
36	// unknownCredentials names the identity of a request whose credentials are not
37	// one of the bench's accounts (wrong password, unknown user, Bearer...).
38	const unknownCredentials = "unrecognized credentials"
39	
40	// route is one recorded exchange, with the fixture it comes from.
41	type route struct {
42		fixture  string
43		identity nexusfixture.Identity
44		ex       nexusfixture.Exchange
45	}
46	
47	// Server answers the recorded exchanges, one httptest server per recorded Host.
48	type Server struct {
49		t testing.TB
50	
51		mu       sync.Mutex // guards hits and the fields set by New
52		hits     map[string]int
53		urls     map[string]string // recorded Host -> fake server URL
54		servers  []*httptest.Server
55		rewriter *strings.Replacer
56	}
57	
58	// New starts one loopback server for each Host the fixtures were recorded on and
59	// closes them with t. A request no fixture answers gets a 501 and a t.Errorf
60	// (never a Fatalf: the handler does not run on the test goroutine).
61	func New(t testing.TB, fixtures ...nexusfixture.Fixture) *Server {
62		t.Helper()
63		s := &Server{t: t, hits: map[string]int{}, urls: map[string]string{}}
64	
65		routes := map[string][]route{}
66		var hosts []string
67		for _, f := range fixtures {
68			for _, ex := range f.Exchanges {
69				if _, ok := routes[ex.Host]; !ok {
70					hosts = append(hosts, ex.Host)
71				}
72				routes[ex.Host] = append(routes[ex.Host], route{fixture: f.Name, identity: f.Identity, ex: ex})
73			}
74		}
75	
76		s.mu.Lock()
77		defer s.mu.Unlock()
78		var pairs []string
79		for _, host := range hosts {
80			srv := httptest.NewServer(s.handler(routes[host]))
81			s.servers = append(s.servers, srv)
82			s.urls[host] = srv.URL
83			pairs = append(pairs, "http://"+host, srv.URL)
84		}
85		s.rewriter = strings.NewReplacer(pairs...)
86		t.Cleanup(func() {
87			for _, srv := range s.servers {
88				srv.Close()
89			}
90		})
91		return s
92	}
93	
94	// URL returns the base URL of the fake server standing for a recorded Host,
95	// such as "127.0.0.1:30481".
96	func (s *Server) URL(recordedHost string) string {
97		s.mu.Lock()
98		defer s.mu.Unlock()
99		u, ok := s.urls[recordedHost]
100		if !ok {
101			s.t.Errorf("fakenexus: no fixture was recorded on host %s", recordedHost)
102		}
103		return u
104	}
105	
106	// Hits counts the requests the named fixture answered, tolerated ones included.
107	func (s *Server) Hits(fixtureName string) int {
108		s.mu.Lock()
109		defer s.mu.Unlock()
110		return s.hits[fixtureName]
111	}
112	
113	func (s *Server) handler(routes []route) http.Handler {
114		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
115			id, known := identify(r)
116			if known {
117				if rt, ok := match(routes, r.Method, r.URL.RequestURI(), id); ok {
118					s.replay(w, rt)
119					return
120				}
121			}
122			label := unknownCredentials
123			if known {
124				label = string(id)
125			}
126			s.t.Errorf("no recorded answer for %s %s as %s", r.Method, r.URL.RequestURI(), label)
127			http.Error(w, "no recorded answer", http.StatusNotImplemented)
128		})
129	}
130	
131	// identify reads the account a request authenticates as. known is false when the
132	// credentials are none of the bench's: that never matches a recording.
133	func identify(r *http.Request) (id nexusfixture.Identity, known bool) {
134		if r.Header.Get("Authorization") == "" {
135			return nexusfixture.Anonymous, true
136		}
137		user, pass, ok := r.BasicAuth()
138		if !ok || pass != Password {
139			return "", false
140		}
141		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull} {
142			if user == User(id) {
143				return id, true
144			}
145		}
146		return "", false
147	}
148	
149	// match picks the exchange recorded for the method, target and identity: the
150	// exact target first, then the catalog tolerance.
151	func match(routes []route, method, target string, id nexusfixture.Identity) (route, bool) {
152		for _, rt := range routes {
153			if rt.identity == id && rt.ex.Method == method && rt.ex.Target == target {
154				return rt, true
155			}
156		}
157		if method != http.MethodGet {
158			return route{}, false
159		}
160		return matchCatalogTolerance(routes, target, id)
161	}
162	
163	// matchCatalogTolerance lets "GET P?n=N" (no "last") be answered by a fixture
164	// recorded as "GET P" without a query, provided that answer is a 200 with no Link
165	// and lists at most N names: one page holds the whole catalog, as with n=N.
166	//
167	// Measured ground: on the group connector, n=1000 and no n answer identically
168	// (page-group-n1000--admin and catalog-group-connector-30482--admin, pinned by
169	// TestTheCatalogToleranceHasMeasuredGround). For hosted and proxy it is an
170	// inference: only no-n and n=2 were measured there.
171	func matchCatalogTolerance(routes []route, target string, id nexusfixture.Identity) (route, bool) {
172		path, rawQuery, _ := strings.Cut(target, "?")
173		query, err := url.ParseQuery(rawQuery)
174		if err != nil || len(query) != 1 || len(query["n"]) != 1 {
175			return route{}, false
176		}
177		n, err := strconv.Atoi(query.Get("n"))
178		if err != nil {
179			return route{}, false
180		}
181		for _, rt := range routes {
182			ex := rt.ex
183			if rt.identity != id || ex.Method != http.MethodGet || ex.Target != path ||
184				ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
185				continue
186			}
187			var catalog struct {
188				Repositories []string `json:"repositories"`
189			}
190			if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
191				return rt, true
192			}
193		}
194		return route{}, false
195	}
196	
197	// rewrittenHeaders carry an address of the recorded host; they are pointed at the
198	// fake server of that host. A body is data and is never rewritten.
199	var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}
200	
201	// replay writes the recorded status, headers and body. Content-Length is never
202	// copied: it is recomputed from the body actually served, since a stub is shorter
203	// than the answer it summarises.
204	func (s *Server) replay(w http.ResponseWriter, rt route) {
205		s.mu.Lock()
206		s.hits[rt.fixture]++
207		rewriter := s.rewriter
208		s.mu.Unlock()
209	
210		ex := rt.ex
211		h := w.Header()
212		for name, values := range ex.Header {
213			if name == "Content-Length" {
214				continue
215			}
216			rewrite := contains(rewrittenHeaders, name)
217			for _, v := range values {
218				if rewrite {
219					v = rewriter.Replace(v)
220				}
221				h.Add(name, v)
222			}
223		}
224		body := bodyOf(ex)
225		h.Set("Content-Length", strconv.Itoa(len(body)))
226		w.WriteHeader(ex.Status)
227		_, _ = w.Write(body)
228	}
229	
230	var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)
231	
232	// bodyOf is the body to serve: the recorded one, or a minimal stand-in for a
233	// summarised body (an HTML page keeps its title; anything else is empty).
234	func bodyOf(ex nexusfixture.Exchange) []byte {
235		if ex.Stub == "" {
236			return ex.Body
237		}
238		if strings.HasPrefix(ex.Stub, "<HTML body omitted:") {
239			if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
240				return []byte("<html><head>" + m[1] + "</head></html>")
241			}
242		}
243		return nil
244	}
245	
246	func contains(list []string, s string) bool {
247		for _, v := range list {
248			if v == s {
249				return true
250			}
251		}
252		return false
253	}
