			if len(errs) == 0 {
				t.Fatalf("a stub %q was replayed as an empty body without a test error", c.stub)
			}
			if !strings.Contains(joined(errs), "stubbed--anon") {
				t.Errorf("errors %q do not name the fixture", errs)
